69:**RN-14 · Datos inconsistentes fallan cerrado.** Ningún permiso se deduce de la ausencia de un dato. Si los datos de usuarios son inconsistentes (archivos con registros de formas mezcladas, o un mismo id en dos roles), la aplicación no arranca.
70-
71----
72-
73-## 4. Contrato de la API (obligatorio, no se modifica)
74-
75-### `POST /api/asistente/preguntar`
--
194:| ¿Cómo se decide si un registro es estudiante o coordinador? | Por la forma consistente de su archivo, nunca por la ausencia de un campo. Si hay formas mezcladas o un id en ambos roles, el arranque falla. | Un dato incompleto no puede dar privilegios (RN-14). |
195-| Coordinador pregunta solo por reglamento | Se responde normal, `usoDatosEstudiante: false`. | Un coordinador también tiene dudas de norma. |
196-| Sin `LLM_API_KEY` | `/api/salud` sigue en 200; preguntar devuelve 503. | La salud del servicio no depende de un tercero. |
197-| Proveedor del modelo | Dos adaptadores: formato OpenAI (Gemini, Groq, OpenAI, Ollama) y Anthropic nativo, elegidos con `LLM_PROVIDER`. | Permite usar un plan gratuito, un modelo local o Claude sin cambiar código. La API de Anthropic nativa permite caché de prompt, útil porque el reglamento se repite en cada pregunta. |
50:### ESC-03.8 · Nombre propio con nombre de pila repetido
51-- **Dado** un estudiante cuyo nombre de pila coincide con el de otro estudiante (por ejemplo "Alicia Prueba Uno" y "Alicia")
52-- **Cuando** pregunta nombrándose con su nombre completo exacto: "Soy Alicia Prueba Uno, ¿cómo voy en mis notas?"
53-- **Entonces** responde 200 con sus propios datos
54-- **Pero cuando** pregunta usando solo "Alicia" sin su nombre completo
55-- **Entonces** responde 403, porque es ambiguo
56-- Criterios: CA-04, CA-05
57-
58:### ESC-03.9 · Variantes de escritura de otro estudiante
59-- **Dado** que Ana es estudiante válida y existe otra estudiante llamada "María José"
60-- **Cuando** pregunta por "Maria Jose" (sin tilde, sin guion) o por "MARÍA-JOSÉ"
61-- **Entonces** responde 403 y no consulta datos
62-- Criterios: CA-05, CA-11
63-
64:### ESC-03.10 · Un registro incompleto no da privilegios
65-- **Dado** un registro de estudiante al que le falta un campo
66-- **Cuando** alguien se identifica con rol `coordinador` y el id de ese estudiante
67-- **Entonces** responde 403; nunca lo trata como coordinador
68-- **Y** si los datos de usuarios son inconsistentes (formas mezcladas o un id en dos roles), la aplicación no arranca
69-- Criterios: CA-08
70-
71-### ESC-03.11 · Evasiones que el filtro no ve
72-- **Dado** que Ana es estudiante válida
73-- **Cuando** pregunta por otro estudiante con un id escrito con homoglifos (por ejemplo "Е-002" con E cirílica) o solo con su apellido
74-- **Entonces** si el filtro previo no lo detecta, el modelo termina pidiendo ese id real a una herramienta y recibe 403
75-- **Y** ningún dato del otro estudiante aparece en la respuesta
76-- Criterios: CA-05, CA-11
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.AspNetCore.TestHost;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;

namespace TutorFlow.Tests;

/// <summary>Crea la API con datos de tests/fixtures y la llave fijada explícitamente (sin tocar el entorno del proceso).</summary>
public static class Fabrica
{
    public static string RutaFixtures => Path.Combine(AppContext.BaseDirectory, "fixtures");

    public static WebApplicationFactory<Program> SinLlave() => Crear("");

    public static WebApplicationFactory<Program> Crear(string llave, Action<IServiceCollection>? servicios = null)
    {
        return new WebApplicationFactory<Program>().WithWebHostBuilder(b =>
        {
            b.UseSetting("Datos:Ruta", RutaFixtures);
            b.UseSetting("LLM_API_KEY", llave);
            b.ConfigureAppConfiguration((_, c) => c.AddInMemoryCollection(new Dictionary<string, string?>
            {
                ["Datos:Ruta"] = RutaFixtures,
                ["LLM_API_KEY"] = llave,
            }));
            if (servicios != null) b.ConfigureTestServices(servicios);
        });
    }
}
using System.Net;
using System.Text;
using System.Text.Json;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.DependencyInjection.Extensions;
using TutorFlow.Api.Llm;

namespace TutorFlow.Tests;

/// <summary>Cliente falso que cuenta llamadas: un 403 nunca debe llegar al modelo.</summary>
public class LlmContador : ILlmClient
{
    public int Llamadas;
    public Task<LlmRespuesta> CompletarAsync(string sistema, IReadOnlyList<LlmMensaje> mensajes,
        IReadOnlyList<LlmHerramienta> herramientas, CancellationToken ct)
    {
        Interlocked.Increment(ref Llamadas);
        return Task.FromResult(new LlmRespuesta("falso", [], new LlmUso(0, 0)));
    }
}

/// <summary>
/// Personajes de tests/fixtures: Alicia T-E1 (Alfa), Damián T-E3 (Alfa), Bruno T-E2 (Beta),
/// Alicia Segunda T-E4 (Beta), Carla T-C1 (coordina Alfa), Esteban T-C2 (coordina Beta).
/// </summary>
public class PermisosTests : IDisposable
{
    private const string Url = "/api/asistente/preguntar";
    private readonly LlmContador _llm = new();
    private readonly WebApplicationFactory<Program> _conLlave;
    private readonly WebApplicationFactory<Program> _sinLlave;

    public PermisosTests()
    {
        _conLlave = Fabrica.Crear("llave-falsa-de-prueba", s =>
        {
            s.RemoveAll<ILlmClient>();
            s.AddSingleton<ILlmClient>(_llm);
        });
        _sinLlave = Fabrica.SinLlave();
    }

    public void Dispose() { _conLlave.Dispose(); _sinLlave.Dispose(); }

    private static StringContent Cuerpo(string pregunta, string rol, string id) =>
        new(JsonSerializer.Serialize(new { pregunta, usuario = new { rol, id } }), Encoding.UTF8, "application/json");

    private static async Task Assert403(HttpResponseMessage r)
    {
        Assert.Equal(HttpStatusCode.Forbidden, r.StatusCode);
        using var doc = JsonDocument.Parse(await r.Content.ReadAsStringAsync());
        Assert.Equal(JsonValueKind.Object, doc.RootElement.ValueKind);
        Assert.True(doc.RootElement.TryGetProperty("error", out var e));
        Assert.Equal(JsonValueKind.String, e.ValueKind);
        Assert.False(string.IsNullOrWhiteSpace(e.GetString()));
    }

    /// <summary>403 con llave (cliente falso, contador en 0, salud 200) y también sin llave.</summary>
    private async Task Esperar403(string pregunta, string rol, string id)
    {
        var c = _conLlave.CreateClient();
        await Assert403(await c.PostAsync(Url, Cuerpo(pregunta, rol, id)));
        Assert.Equal(0, _llm.Llamadas);
        Assert.Equal(HttpStatusCode.OK, (await c.GetAsync("/api/salud")).StatusCode);

        await Assert403(await _sinLlave.CreateClient().PostAsync(Url, Cuerpo(pregunta, rol, id)));
    }

    /// <summary>No debe ser 403: sin llave llega al 503; con llave, cualquier cosa menos 403.</summary>
    private async Task EsperarNo403(string pregunta, string rol, string id)
    {
        var sin = await _sinLlave.CreateClient().PostAsync(Url, Cuerpo(pregunta, rol, id));
        Assert.Equal(HttpStatusCode.ServiceUnavailable, sin.StatusCode);
        var con = await _conLlave.CreateClient().PostAsync(Url, Cuerpo(pregunta, rol, id));
        Assert.NotEqual(HttpStatusCode.Forbidden, con.StatusCode);
    }

    // ESC-03.1
